function updateHUD() {
  if(!levelsData.length) return;
  const lvl = levelsData[currentLevelIndex];
  hudLevelEl.textContent = `${lvl.icon||'🌾'} ${lvl.name}`;
  // progress = total unique words planted this session
  const pct = lvl.words.length > 0 ? Math.min(100, Math.round((progress / lvl.words.length) * 100)) : 0;
  hudProgressEl.textContent = `🌱 ${progress} words`;
  if(pbFill) pbFill.style.width = pct + '%';
  updateGoldHUD();
}

// ═══════════════ LEVEL SELECT ════════════════════════════════════════════════
function buildLevelSelectScreen() {
  if(!lsGrid) return;
  if(!levelsData || !levelsData.length){
    if(typeof sceneRef !== 'undefined' && sceneRef?.cache?.json){
      levelsData = sceneRef.cache.json.get('levels') || [];
    }
    if(!levelsData || !levelsData.length){
      fetch('levels.json').then(r => r.json()).then(d => {
        levelsData = d;
        buildLevelSelectScreen();
      }).catch(err => console.error('Failed to load levels.json:', err));
      return;
    }
  }
  lsGrid.innerHTML = '';
  // ── RESUME BUTTON (shown when there's saved progress) ──────────────────────
  const hasSave = plotSave.length > 0 || gold > 0 || harvestCounts.size > 0;
  if(hasSave){
    const r = document.createElement('div');
    r.className = 'ls-resume-card';
    const planted = plotSave.length;
    r.innerHTML = `
      <div class="lsr-icon">▶</div>
      <div class="lsr-text">
        <div class="lsr-title">Continue Previous Session</div>
        <div class="lsr-sub">💰 ${gold} gold &nbsp;|&nbsp; 🌱 ${planted} crops growing &nbsp;|&nbsp; Level ${currentLevelIndex+1}</div>
      </div>`;
    r.addEventListener('click', resumeGame);
    lsGrid.appendChild(r);
  }
  // Separator if resume exists
  if(hasSave){
    const sep=document.createElement('div');
    sep.className='ls-sep';
    sep.textContent='── or select a level ──';
    lsGrid.appendChild(sep);
  }
  levelsData.forEach((lvl, idx) => {
    const owned = unlockedLevels.includes(idx);
    const cost  = LEVEL_COST(idx);
    const canAfford = gold >= cost;

    const c = document.createElement('div');
    c.className = 'level-card' + (!owned ? ' locked' : '');
    c.innerHTML = `<div class="lc-badge">${owned ? '✅' : (canAfford ? '💰' : '🔒')}</div>
      <div class="lc-top"><span class="lc-icon">${lvl.icon||'📚'}</span>
      <div class="lc-meta"><div class="lc-num">Level ${lvl.level}</div>
      <div class="lc-name">${lvl.name}</div></div></div>
      <div class="lc-desc">${lvl.description||''}</div>
      <div class="lc-footer">
        <span class="lc-tag words">📝 ${lvl.words.length} words</span>
        ${owned ? `<span class="lc-tag" style="color:#4ade80">✅ Owned</span>`
                : `<span class="lc-tag target" style="color:${canAfford?'#f9c74f':'#aaa'}">💰 ${cost} gold</span>`}
      </div>`;
    if(owned) {
      // If clicking the CURRENT level → resume; if switching → confirm reset
      c.addEventListener('click', () => {
        if(idx === currentLevelIndex && hasSave){
          resumeGame(); // same level: just resume
        } else {
          startLevel(idx, true); // different level or no save: fresh start
        }
      });
    } else if(canAfford) {
      c.addEventListener('click', () => { buyLevelFromSelect(idx); });
      c.title='Click to buy!';
    }
    lsGrid.appendChild(c);
  });
}
// ═══════════════ CENTRALIZED UI GLASSMORPHISM MODAL MANAGER ═══════════════════
let activeModalStack = [];

function setModalState(overlayId, isOpen) {
  const overlay = document.getElementById(overlayId);
  if (!overlay) return;
  if (isOpen) {
    overlay.classList.add('visible');
    overlay.classList.remove('hidden');
    playerLocked = true;
    if (!activeModalStack.includes(overlayId)) {
      activeModalStack.push(overlayId);
    }
  } else {
    overlay.classList.remove('visible');
    if (overlayId === 'level-select-overlay') {
      overlay.classList.add('hidden');
    }
    activeModalStack = activeModalStack.filter(id => id !== overlayId);
    if (activeModalStack.length === 0) {
      playerLocked = false;
    }
  }
}

function closeTopModal() {
  if (activeModalStack.length === 0) return false;
  const topId = activeModalStack[activeModalStack.length - 1];
  closeModalById(topId);
  return true;
}

function closeModalById(overlayId) {
  if (overlayId === 'inventory-overlay') window.closeInventoryUI();
  else if (overlayId === 'cooking-overlay') window.closeCookingUI();
  else if (overlayId === 'fish-album-overlay') window.closeFishAlbum();
  else if (overlayId === 'recipe-overlay') window.closeRecipeBook();
  else if (overlayId === 'seasonal-overlay') window.closeSeasonalOverlay();
  else if (overlayId === 'leaderboard-overlay') window.closeLeaderboard();
  else if (overlayId === 'shop-overlay') window.closeShop();
  else if (overlayId === 'memory-overlay') window.closeMemoryGame();
  else if (overlayId === 'duel-overlay') window.closeSpellDuel();
  else if (overlayId === 'hangul-overlay') window.closeHangulLab();
  else if (overlayId === 'learning-path-overlay') window.closeLearningPath();
  else if (overlayId === 'world-learning-overlay') window.closeWorldLearning();
  else if (overlayId === 'trophy-overlay') window.closeTrophies();
  else if (overlayId === 'level-select-overlay') hideLevelSelect();
  else setModalState(overlayId, false);
}

if (typeof window !== 'undefined' && window.addEventListener) {
  window.addEventListener('keydown', (e) => {
    const activeEl = document.activeElement;
    const isInputFocused = activeEl && (
      activeEl.tagName === 'INPUT' ||
      activeEl.tagName === 'TEXTAREA' ||
      activeEl.isContentEditable
    );

    if (e.key === 'Escape' && activeModalStack.length > 0) {
      closeTopModal();
      return;
    }

    if (!isInputFocused) {
      if (e.key === 'i' || e.key === 'I' || e.key === 'e' || e.key === 'E') {
        if (activeModalStack.length > 0 && activeModalStack[activeModalStack.length - 1] === 'inventory-overlay') {
          window.closeInventoryUI();
        } else if (activeModalStack.length === 0) {
          window.openInventoryUI();
        }
      }
      if (e.key === 'c' || e.key === 'C') {
        if (activeModalStack.length > 0 && activeModalStack[activeModalStack.length - 1] === 'cooking-overlay') {
          window.closeCookingUI();
        } else if (activeModalStack.length === 0) {
          window.openCookingUI();
        }
      }
    }
  });
}

function openInventoryUI() {
  if (typeof playChiptuneSFX === 'function') playChiptuneSFX('click');
  renderInventoryGrid();
  setModalState('inventory-overlay', true);
}

function closeInventoryUI() {
  if (typeof playChiptuneSFX === 'function') playChiptuneSFX('click');
  setModalState('inventory-overlay', false);
}

function renderInventoryGrid() {
  const grid = document.getElementById('inventory-grid');
  const badge = document.getElementById('inv-capacity-badge');
  const capText = document.getElementById('inv-capacity-text');

  inventoryState = inventoryState || {};
  const maxSlots = typeof inventoryState.maxSlots === 'number' ? inventoryState.maxSlots : 20;
  inventoryState.maxSlots = maxSlots;
  const usedSlots = getUsedInventorySlots();

  if (badge) badge.textContent = `${usedSlots} / ${maxSlots} slots`;
  if (capText) capText.textContent = `${maxSlots} slots`;

  if (!grid) return;
  grid.innerHTML = '';

  const items = [];

  // 1. Ingredients
  if (inventoryState.ingredients) {
    for (const [nameKo, qty] of Object.entries(inventoryState.ingredients)) {
      if (qty > 0) {
        const info = getItemInfo(nameKo);
        items.push({
          itemId: info.id || nameKo,
          name: info.name || nameKo,
          nameKo: info.nameKo || nameKo,
          qty: qty,
          icon: info.icon || '🥬',
          description: info.description || 'Harvested crop / ingredient'
        });
      }
    }
  }

  // 2. Cooked Dishes
  if (inventoryState.cookedDishes) {
    for (const [recipeId, qty] of Object.entries(inventoryState.cookedDishes)) {
      if (qty > 0) {
        let nameKo = recipeId;
        let nameEn = recipeId;
        let icon = '🍱';
        if (typeof COOKING_RECIPES !== 'undefined' && Array.isArray(COOKING_RECIPES)) {
          const rec = COOKING_RECIPES.find(r => r.id === recipeId);
          if (rec) {
            nameKo = rec.name;
            nameEn = rec.enName || rec.name;
            icon = rec.icon || '🍱';
          }
        }
        items.push({
          itemId: recipeId,
          name: nameEn,
          nameKo: nameKo,
          qty: qty,
          icon: icon,
          description: 'Delicious cooked dish'
        });
      }
    }
  }

  // Render slots up to maxSlots
  for (let i = 0; i < maxSlots; i++) {
    const slotEl = document.createElement('div');
    if (i < items.length) {
      const item = items[i];
      slotEl.className = 'inv-slot';
      slotEl.title = `${item.nameKo} (${item.name}): ${item.description}`;
      slotEl.innerHTML = `
        <div class="inv-qty-badge">x${item.qty}</div>
        <div class="inv-slot-icon">${item.icon}</div>
        <div class="inv-slot-ko">${item.nameKo}</div>
        <div class="inv-slot-en">${item.name}</div>
      `;
    } else {
      slotEl.className = 'inv-slot empty';
      slotEl.innerHTML = `
        <div style="font-size:22px; opacity:0.3; margin-bottom:4px;">📦</div>
        <div style="font-size:11px; color:rgba(255,255,255,0.3); font-family:'Press Start 2P',monospace;">Empty</div>
      `;
    }
    grid.appendChild(slotEl);
  }
}

if (typeof window !== 'undefined') {
  window.openInventoryUI = openInventoryUI;
  window.closeInventoryUI = closeInventoryUI;
  window.renderInventoryGrid = renderInventoryGrid;
  window.expandInventoryCapacity = expandInventoryCapacity;
  window.addItemToInventory = addItemToInventory;
  window.removeItemFromInventory = removeItemFromInventory;
  window.getUsedInventorySlots = getUsedInventorySlots;
  window.openCookingUI = openCookingUI;
  window.closeCookingUI = closeCookingUI;
  window.renderCookingGrid = renderCookingGrid;
  window.cookRecipe = cookRecipe;
  window.checkCookingAchievements = checkCookingAchievements;
}

function showLevelSelect() {
  setModalState('level-select-overlay', true);
  hud.style.display = pbWrap.style.display = tipEl.style.display = 'none';
  buildLevelSelectScreen();
}
function hideLevelSelect() {
  setModalState('level-select-overlay', false);
  hud.style.display = pbWrap.style.display = tipEl.style.display = '';
}

function buyLevelFromSelect(idx) {
  playChiptuneSFX('click');
  const cost = LEVEL_COST(idx);
  if (unlockedLevels.includes(idx)) { showToast('You already own this pack!'); return; }
  const gate = getPackLearningGate(idx);
  if (!gate.allowed) { showToast(gate.message, 4000); return; }
  if (playerCurrencies.coins < cost) { showToast(`Need ${cost} Coins! You have ${playerCurrencies.coins} 🪙`); return; }
  startShopQuizGate(idx);
}

function getPackLearningGate(idx) {
  if (idx <= 0) return { allowed: true };
  if (!unlockedLevels.includes(idx - 1)) {
    return { allowed: false, message: `📚 Complete the story in Level ${idx} before opening this pack.` };
  }
  const target = Math.min(35, 8 + Math.floor((idx - 1) / 3) * 3);
  const mastery = calcLevelMastery(idx - 1);
  return {
    allowed: mastery >= target,
    mastery,
    target,
    message: `🧠 Reach ${target}% learning mastery in ${levelsData[idx - 1]?.name || `Level ${idx}`} first. Current: ${mastery}%`
  };
}

// ═══════════════ START LEVEL / RESUME ═════════════════════════════════════════
function startLevel(idx, resetCrops=true) {
  currentLevelIndex = idx;
  try { localStorage.setItem('hv_lastLevel', String(idx)); } catch {}
  if(resetCrops){
    // Full fresh start: wipe everything
    progress = 0; plantedWords.clear();
    if(sceneRef) sceneRef.resetPlots(); // also removes hv_plots from localStorage
    plotSave = [];
  }
  hideLevelSelect();
  updateHUD(); updateVocabBook();
  persistSave(); // save the chosen level
}
// Resume last session WITHOUT resetting crops
function resumeGame(){
  currentLevelIndex = parseInt(localStorage.getItem('hv_lastLevel')||'0') || currentLevelIndex;
  hideLevelSelect();
  updateHUD(); updateVocabBook();
  showToast('▶ Resumed previous session!');
}

// ────── HANGUL CHOSUNG & ROMANIZATION HELPERS ─────────────────────────
const CHOSUNG_LIST = ['ㄱ','ㄲ','ㄴ','ㄷ','ㄸ','ㄹ','ㅁ','ㅂ','ㅃ','ㅅ','ㅆ','ㅇ','ㅈ','ㅉ','ㅊ','ㅋ','ㅌ','ㅍ','ㅎ'];
function getChosung(str){
  if(!str) return '';
  let res = '';
  for(let i = 0; i < str.length; i++){
    const code = str.charCodeAt(i) - 44032;
    if(code >= 0 && code <= 11172){
      res += CHOSUNG_LIST[Math.floor(code / 588)];
    } else {
      res += str[i];
    }
  }
  return res;
}

const ROMAN_MAP = {
  '사과':'sa-gwa', '우유':'u-yu', '빵':'ppang', '밥':'bap', '생선':'saeng-seon',
  '고기':'go-gi', '계란':'gye-ran', '채소':'chae-so', '과일':'gwa-il', '커피':'keo-pi',
  '차':'cha', '주스':'ju-seu', '태양':'tae-yang', '달':'dal', '별':'byeol',
  '하늘':'ha-neul', '산':'san', '바다':'ba-da', '강':'gang', '나무':'na-mu',
  '꽃':'kkot', '눈':'nun', '코':'ko', '입':'ip', '손':'son',
  '발':'bal', '머리':'meo-ri', '마음':'ma-eum', '고양이':'go-yang-i', '개':'gae',
  '새':'sae', '학교':'hak-gyo', '병원':'byeong-won', '시장':'si-jang', '전화':'jeon-hwa',
  '물':'mul'
};
function getRoman(ko){
  return ROMAN_MAP[ko] || (window.HVLearning ? window.HVLearning.romanizeHangul(ko) : ko);
}

function speakKorean(text) {
  if (!('speechSynthesis' in window) || typeof SpeechSynthesisUtterance === 'undefined') {
    showToast('🔇 Korean speech is not available in this browser.', 2500);
    return false;
  }
  window.speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = 'ko-KR';
  utterance.rate = 0.82;
  const voices = window.speechSynthesis.getVoices();
  const koreanVoice = voices.find(voice => String(voice.lang).toLowerCase().startsWith('ko'));
  if (koreanVoice) utterance.voice = koreanVoice;
  window.speechSynthesis.speak(utterance);
  return true;
}

function revealQuizHint(tier){
  if(!currentWord) return;
  playChiptuneSFX('click');
  const box = $('quiz-hint-reveal-card');
  if(!box) return;
  let revealed = false;
  
  if(tier === 'audio'){
    if (!speakKorean(currentWord.ko)) return;
    recordLearningExposure(currentWord, 'audio_hint');
    box.innerHTML = `🔊 <b>Listen & repeat:</b> <span lang="ko" style="color:#67e8f9;font-weight:bold">${currentWord.ko}</span>`;
    revealed = true;
  } else if(tier === 'roman'){
    const rom = getRoman(currentWord.ko);
    box.innerHTML = `🔤 <b>Romanization:</b> <span style="color:#67e8f9; font-weight:bold">[${rom}]</span>`;
    revealed = true;
  } else if(tier === 'chosung'){
    if (quizFreeHintsRemaining > 0) quizFreeHintsRemaining--;
    else if(!spendCoins(5)){ showToast('Need 5 Coins 🪙 for Chosung hint!'); return; }
    const ch = getChosung(currentWord.ko);
    box.innerHTML = `🔠 <b>Initial Consonants (초성):</b> <span style="color:#fde047; font-size:18px; font-weight:bold; letter-spacing:3px">${ch}</span>`;
    revealed = true;
  } else if(tier === 'fact'){
    if (quizFreeHintsRemaining > 0) quizFreeHintsRemaining--;
    else if(!spendCoins(10)){ showToast('Need 10 Coins 🪙 for Han-Viet hint!'); return; }
    const fact = getFunFact(currentWord);
    box.innerHTML = `💡 <b>Memory Tip:</b> ${fact.vi || fact.ko || 'A useful Korean word!'}`;
    revealed = true;
  }
  if (revealed) quizHintsUsed++;
  box.classList.remove('hidden');
}

// ====== QUIZ (SRS Phase-Aware) ================================================
let currentPhase = 1;
let quizStartedAt = 0;
let quizHintsUsed = 0;
let quizFreeHintsRemaining = 0;
function openQuiz(word, plot, phase=1){
  if(quizOpen) return;
  currentWord=word; currentPlot=plot; currentPhase=phase;
  quizStartedAt=Date.now(); quizHintsUsed=0;
  quizFreeHintsRemaining = Math.max(0, Math.floor(getBuff('quiz_hints')?.value || 0));
  quizOpen=playerLocked=true;
  
  // Reset tier hint reveal card
  const hc = $('quiz-hint-reveal-card'); if(hc) { hc.innerHTML = ''; hc.classList.add('hidden'); }

  const cfg=PHASE_CFG[phase-1];
  // Phase bar UI
  const pi=$('quiz-phase-icon'); if(pi) pi.textContent=cfg.icon;
  const pt=$('quiz-phase-title'); if(pt) pt.textContent=cfg.title;
  const pn=$('quiz-phase-name'); if(pn) pn.textContent=cfg.icon+' '+cfg.title;
  const pd=$('quiz-phase-dots'); if(pd) pd.textContent=cfg.dots;
  const gr=$('quiz-gold-reward'); if(gr) gr.textContent=cfg.reward;
  const sb=$('submit-btn'); if(sb) sb.textContent=cfg.btn;
  const qui=$('quiz-ui'); if(qui) qui.className='phase-'+phase;
  // Fill data (CSS controls visibility per phase)
  hintEmoji.textContent     = word.hint||'?';
  hintCategory.textContent  = word.category||'';
  enWordDisplay.textContent = word.en;
  quizLevelTag.textContent  = 'P'+phase+'/3';
  // Phase 3: populate fun-fact recall hints
  const ffText=$('quiz-funfact-text'), ffCulture=$('quiz-funfact-culture');
  if(ffText && ffCulture){
    if(phase===3){
      const fact = getFunFact(word);
      ffText.textContent    = fact.ko || '';
      ffCulture.textContent = fact.vi || '';
    } else {
      ffText.textContent = ''; ffCulture.textContent = '';
    }
  }
  answerInput.value=''; feedbackText.textContent=''; feedbackText.className='';
  quizBackdrop.classList.add('visible');
  setTimeout(()=>answerInput.focus(),80);
}
function closeQuiz(){
  playChiptuneSFX('click');
  quizOpen=playerLocked=false;
  appleTreeQuizPending=false; // always reset on close
  const hc = $('quiz-hint-reveal-card'); if(hc) { hc.innerHTML = ''; hc.classList.add('hidden'); }
  quizBackdrop.classList.remove('visible');
  const qui=$('quiz-ui'); if(qui) qui.className='';
  currentWord=currentPlot=null;
}
function submitAnswer(){
  if(!currentWord) return;
  const typed=answerInput.value;
  const isCorrect = window.HVLearning
    ? window.HVLearning.isAnswerCorrect(typed, currentWord)
    : typed.trim()===currentWord.ko;
  recordLearningAttempt(currentWord, {
    activity: appleTreeQuizPending ? 'apple_tree' : `farm_phase_${currentPhase}`,
    modality: 'production',
    correct: isCorrect,
    responseMs: Date.now() - quizStartedAt,
    hints: quizHintsUsed
  });
  if(isCorrect){
    playChiptuneSFX('quiz_correct');
    const quizPanel = $('quiz-ui');
    if (quizPanel) quizPanel.classList.add('celebrate');
    if (sceneRef?.feedback) sceneRef.feedback.correctAtPlayer();
    // ── Apple Tree harvest (special Phase 3 quiz) ─────────────────────────
    if(appleTreeQuizPending){
      feedbackText.textContent='🍎 Harvested! Excellent Korean!'; feedbackText.className='correct';
      appleTreeQuizPending=false;
      setTimeout(()=>{ closeQuiz(); if(sceneRef) sceneRef.onAppleHarvested(); },700);
      return;
    }
    // ── Normal crop quiz ──────────────────────────────────────────────────
    const msgs=['🌱 Planted! Remember to water!','💧 Watered! Almost ripe!','🍎 Excellent! +Gold earned!'];
    feedbackText.textContent=msgs[currentPhase-1]; feedbackText.className='correct';
    const cp=currentPlot, cw=currentWord, ph=currentPhase;
    if(ph===1){plantedWords.add(cw.ko); progress++; updateHUD(); updateVocabBook();}
    setTimeout(()=>{ closeQuiz(); if(sceneRef) sceneRef.advancePlot(cp,cw,ph); },650);
  } else {
    playChiptuneSFX('quiz_wrong');
    const isApple = appleTreeQuizPending;
    const wrong = isApple ? '❌ Wrong! Try again to harvest!' : (currentPhase===3?'❌ Wrong! Plant regressed to Phase 2!':'❌ Wrong! Try again.');
    feedbackText.textContent=wrong; feedbackText.className='';
    answerInput.value=''; answerInput.focus();
    answerInput.animate(
      [{transform:'translateX(-7px)'},{transform:'translateX(7px)'},{transform:'translateX(0)'}],
      {duration:260,easing:'ease-out'});
    // Apple tree quiz: no regression, just retry
    if(!isApple && currentPhase===3){
      const cp=currentPlot, cw=currentWord;
      appleTreeQuizPending=false;
      setTimeout(()=>{ closeQuiz(); if(sceneRef) sceneRef.regressionPlot(cp,cw); },1400);
    }
  }
}
submitBtn.addEventListener('click', submitAnswer);
cancelBtn.addEventListener('click', closeQuiz);
answerInput.addEventListener('keydown', e => {
  if((e.isComposing || e.keyCode === 229)) { e.stopPropagation(); return; }
  if(e.key==='Enter'){e.preventDefault();submitAnswer();}
  if(e.key==='Escape') closeQuiz();
  e.stopPropagation();
});
quizBackdrop.addEventListener('keydown', e => e.stopPropagation());
quizBackdrop.addEventListener('keyup',   e => e.stopPropagation());

// ═══════════════ HANGUL FOUNDATIONS LAB ══════════════════════════════════════
const HANGUL_LAB_INITIALS = [
  { jamo:'ㄱ', index:0, roman:'g/k' }, { jamo:'ㄴ', index:2, roman:'n' },
  { jamo:'ㄷ', index:3, roman:'d/t' }, { jamo:'ㄹ', index:5, roman:'r/l' },
  { jamo:'ㅁ', index:6, roman:'m' }, { jamo:'ㅂ', index:7, roman:'b/p' },
  { jamo:'ㅅ', index:9, roman:'s' }, { jamo:'ㅇ', index:11, roman:'-/ng' },
  { jamo:'ㅈ', index:12, roman:'j' }, { jamo:'ㅊ', index:14, roman:'ch' },
  { jamo:'ㅋ', index:15, roman:'k' }, { jamo:'ㅌ', index:16, roman:'t' },
  { jamo:'ㅍ', index:17, roman:'p' }, { jamo:'ㅎ', index:18, roman:'h' }
];
const HANGUL_LAB_VOWELS = [
  { jamo:'ㅏ', index:0, roman:'a' }, { jamo:'ㅑ', index:2, roman:'ya' },
  { jamo:'ㅓ', index:4, roman:'eo' }, { jamo:'ㅕ', index:6, roman:'yeo' },
  { jamo:'ㅗ', index:8, roman:'o' }, { jamo:'ㅛ', index:12, roman:'yo' },
  { jamo:'ㅜ', index:13, roman:'u' }, { jamo:'ㅠ', index:17, roman:'yu' },
  { jamo:'ㅡ', index:18, roman:'eu' }, { jamo:'ㅣ', index:20, roman:'i' }
];
let hangulLabState = { initial:0, vowel:0, quiz:null, startedAt:0 };

function composeHangulSyllable(initialIndex, vowelIndex, finalIndex = 0) {
  return String.fromCharCode(0xAC00 + ((initialIndex * 21 + vowelIndex) * 28) + finalIndex);
}

function currentHangulLabWord() {
  const initial = HANGUL_LAB_INITIALS[hangulLabState.initial];
  const vowel = HANGUL_LAB_VOWELS[hangulLabState.vowel];
  const ko = composeHangulSyllable(initial.index, vowel.index);
  return { id:`hangul_${ko}`, ko, en:window.HVLearning ? window.HVLearning.romanizeHangul(ko) : `${initial.roman}${vowel.roman}`, category:'한글 기초' };
}

function renderHangulLab() {
  const initialGrid = document.getElementById('hangul-initial-grid');
  const vowelGrid = document.getElementById('hangul-vowel-grid');
  if (!initialGrid || !vowelGrid) return;
  initialGrid.innerHTML = '';
  vowelGrid.innerHTML = '';

  HANGUL_LAB_INITIALS.forEach((item, index) => {
    const button = document.createElement('button');
    button.className = `hangul-choice${index === hangulLabState.initial ? ' selected' : ''}`;
    button.innerHTML = `${item.jamo}<small>${item.roman}</small>`;
    button.onclick = () => { hangulLabState.initial = index; renderHangulLab(); };
    initialGrid.appendChild(button);
  });
  HANGUL_LAB_VOWELS.forEach((item, index) => {
    const button = document.createElement('button');
    button.className = `hangul-choice${index === hangulLabState.vowel ? ' selected' : ''}`;
    button.innerHTML = `${item.jamo}<small>${item.roman}</small>`;
    button.onclick = () => { hangulLabState.vowel = index; renderHangulLab(); };
    vowelGrid.appendChild(button);
  });

  const word = currentHangulLabWord();
  const result = document.getElementById('hangul-builder-result');
  const roman = document.getElementById('hangul-builder-roman');
  if (result) result.textContent = word.ko;
  if (roman) roman.textContent = `[${word.en}]`;
}

window.openHangulLab = function() {
  playChiptuneSFX('click');
  renderHangulLab();
  startHangulQuiz();
  setModalState('hangul-overlay', true);
};

window.closeHangulLab = function() {
  playChiptuneSFX('click');
  setModalState('hangul-overlay', false);
};

window.speakHangulBuilder = function() {
  const word = currentHangulLabWord();
  if (speakKorean(word.ko)) recordLearningExposure(word, 'hangul_builder_audio');
};

window.startHangulQuiz = function() {
  const initial = Phaser.Utils.Array.GetRandom(HANGUL_LAB_INITIALS);
  const vowel = Phaser.Utils.Array.GetRandom(HANGUL_LAB_VOWELS);
  const target = {
    id:`hangul_${composeHangulSyllable(initial.index, vowel.index)}`,
    ko:composeHangulSyllable(initial.index, vowel.index),
    en:window.HVLearning ? window.HVLearning.romanizeHangul(composeHangulSyllable(initial.index, vowel.index)) : `${initial.roman}${vowel.roman}`,
    category:'한글 기초'
  };
  const options = [target];
  while (options.length < 4) {
    const randomInitial = Phaser.Utils.Array.GetRandom(HANGUL_LAB_INITIALS);
    const randomVowel = Phaser.Utils.Array.GetRandom(HANGUL_LAB_VOWELS);
    const ko = composeHangulSyllable(randomInitial.index, randomVowel.index);
    if (!options.some(option => option.ko === ko)) {
      options.push({ id:`hangul_${ko}`, ko, en:window.HVLearning ? window.HVLearning.romanizeHangul(ko) : '', category:'한글 기초' });
    }
  }
  Phaser.Utils.Array.Shuffle(options);
  hangulLabState.quiz = target;
  hangulLabState.startedAt = Date.now();
  const prompt = document.getElementById('hangul-quiz-prompt');
  if (prompt) prompt.textContent = `Which syllable block is read as [${target.en}]?`;
  const container = document.getElementById('hangul-quiz-options');
  if (!container) return;
  container.innerHTML = '';
  options.forEach(option => {
    const button = document.createElement('button');
    button.className = 'hangul-choice';
    button.textContent = option.ko;
    button.onclick = () => answerHangulQuiz(option.ko === target.ko, button);
    container.appendChild(button);
  });
};

function answerHangulQuiz(isCorrect, button) {
  const target = hangulLabState.quiz;
  if (!target) return;
  recordLearningAttempt(target, {
    activity:'hangul_lab',
    modality:'recognition',
    correct:isCorrect,
    responseMs:Date.now() - hangulLabState.startedAt
  });
  if (isCorrect) {
    playChiptuneSFX('quiz_correct');
    button.classList.add('selected');
    showToast(`✅ ${target.ko} = [${target.en}]`, 1800);
    setTimeout(startHangulQuiz, 500);
  } else {
    playChiptuneSFX('quiz_wrong');
    const quizPanel = $('quiz-ui');
    if (quizPanel) quizPanel.classList.remove('celebrate');
    button.style.borderColor = '#ef4444';
    showToast(`❌ Listen and try again [${target.en}].`, 1800);
  }
}

// ═══════════════ GINGER'S KOREAN LEARNING PATH ═══════════════════════════════
let learningPathUiState = { chapterId:null, missionIndex:0, missionStartedAt:0, running:false, locked:false };

function escapeLearningHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function getCurriculumChapters() {
  return Array.isArray(window.HVCurriculum?.chapters) ? window.HVCurriculum.chapters : [];
}

function resolveCurriculumWord(ko) {
  const existing = getAllLearningWords().find(word => word.ko === ko);
  if (existing) return existing;
  return {
    id:`curriculum_${ko}`,
    ko,
    en:window.HVLearning ? window.HVLearning.romanizeHangul(ko) : ko,
    category:'문맥 학습'
  };
}

function getChapterLearningMastery(chapter) {
  if (!window.HVLearning || !chapter?.wordRefs?.length) return 0;
  const total = chapter.wordRefs.reduce((sum, ko) => sum + window.HVLearning.getMastery(resolveCurriculumWord(ko)), 0);
  return Math.round(total / chapter.wordRefs.length);
}

function getRecommendedChapterId() {
  const chapters = getCurriculumChapters();
  const unfinished = chapters.find(chapter => !curriculumState.completedChapters.includes(chapter.id));
  return unfinished?.id || chapters[chapters.length - 1]?.id || null;
}

function getChapterAttemptStats(chapterId) {
  const current = curriculumState.chapterAttempts[chapterId];
  if (current && typeof current === 'object') return current;
  const created = { runs:0, correct:0, incorrect:0, lastPlayedAt:0 };
  curriculumState.chapterAttempts[chapterId] = created;
  return created;
}

function renderLearningPath() {
  const chapters = getCurriculumChapters();
  const list = document.getElementById('learning-chapter-list');
  const detail = document.getElementById('learning-chapter-detail');
  const summary = document.getElementById('learning-path-summary');
  const qaNote = document.getElementById('learning-qa-note');
  if (!list || !detail) return;
  if (!chapters.length) {
    detail.innerHTML = '<div class="learning-card">Curriculum data is unavailable.</div>';
    return;
  }

  const selectedId = learningPathUiState.chapterId || curriculumState.activeChapterId || getRecommendedChapterId();
  const selected = chapters.find(chapter => chapter.id === selectedId) || chapters[0];
  learningPathUiState.chapterId = selected.id;
  curriculumState.activeChapterId = selected.id;

  const completedCount = curriculumState.completedChapters.length;
  if (summary) {
    summary.textContent = `${completedCount}/${chapters.length} chapters complete · learn words in sentences · practice in context`;
  }
  if (qaNote) {
    qaNote.textContent = `🧪 QA: ${window.HVCurriculum?.qa?.noteVi || 'Content is awaiting language review.'}`;
  }

  list.innerHTML = '';
  chapters.forEach(chapter => {
    const completed = curriculumState.completedChapters.includes(chapter.id);
    const button = document.createElement('button');
    button.className = `learning-chapter-card${chapter.id === selected.id ? ' active' : ''}${completed ? ' completed' : ''}`;
    button.innerHTML = `
      <div class="learning-chapter-title">${chapter.icon} ${chapter.order}. ${escapeLearningHtml(chapter.titleVi)} ${completed ? '✅' : ''}</div>
      <div class="learning-chapter-meta">${chapter.band} · ${escapeLearningHtml(chapter.titleKo)} · mastery ${getChapterLearningMastery(chapter)}%</div>
    `;
    button.onclick = () => selectLearningChapter(chapter.id);
    list.appendChild(button);
  });

  renderLearningChapterDetail(selected);
}

function renderLearningChapterDetail(chapter) {
  const detail = document.getElementById('learning-chapter-detail');
  if (!detail || !chapter) return;
  const stats = getChapterAttemptStats(chapter.id);
  const grammarHtml = chapter.grammar.map(point => `
    <div class="learning-card">
      <div style="color:#fde047;font-weight:900;font-family:'Noto Sans KR',sans-serif;">${escapeLearningHtml(point.form)}</div>
      <div style="color:#cbd5e1;margin-top:5px;">${escapeLearningHtml(point.meaningVi)}</div>
      ${point.examples.map(example => `
        <div style="margin-top:9px;padding:9px;border-left:3px solid #a78bfa;background:rgba(124,58,237,.1);">
          <div lang="ko" style="font-family:'Noto Sans KR',sans-serif;font-size:19px;">${escapeLearningHtml(example.ko)}
            <button class="hud-btn learning-audio-btn" data-ko="${escapeLearningHtml(example.ko)}" style="padding:3px 7px;margin-left:5px;">🔊</button>
          </div>
          <div style="color:#94a3b8;font-size:12px;margin-top:3px;">${escapeLearningHtml(example.vi)}</div>
        </div>
      `).join('')}
    </div>
  `).join('');
  const dialogueHtml = chapter.dialogue.map(line => `
    <div class="learning-dialogue-line">
      <div class="learning-speaker">${escapeLearningHtml(line.speaker)}</div>
      <div>
        <div lang="ko" style="font-family:'Noto Sans KR',sans-serif;font-size:18px;">${escapeLearningHtml(line.ko)}</div>
        <div style="color:#94a3b8;font-size:12px;">${escapeLearningHtml(line.vi)}</div>
      </div>
    </div>
  `).join('');
  const completed = curriculumState.completedChapters.includes(chapter.id);

  detail.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;">
      <div>
        <div style="color:#c4b5fd;font-family:'Press Start 2P',monospace;font-size:12px;">${chapter.icon} CHAPTER ${chapter.order} · ${chapter.band}</div>
        <h2 style="margin:9px 0 2px;color:#fff;">${escapeLearningHtml(chapter.titleVi)}</h2>
        <div lang="ko" style="color:#67e8f9;font-family:'Noto Sans KR',sans-serif;font-size:20px;">${escapeLearningHtml(chapter.titleKo)}</div>
      </div>
      <div style="text-align:right;color:${completed ? '#4ade80' : '#94a3b8'};font-weight:900;">${completed ? '✅ COMPLETE' : `${getChapterLearningMastery(chapter)}% MASTERY`}</div>
    </div>
    <div class="learning-card"><strong style="color:#f9a8d4;">🎯 Can-do:</strong> ${escapeLearningHtml(chapter.canDoVi)}</div>
    ${grammarHtml}
    <div class="learning-card">
      <div style="color:#f9a8d4;font-weight:900;margin-bottom:6px;">🐱 DIALOGUE WITH GINGER</div>
      ${dialogueHtml}
      <button class="hud-btn learning-dialogue-audio" style="margin-top:7px;">🔊 Listen to dialogue</button>
    </div>
    <div id="context-mission-box" class="learning-card">
      <div style="display:flex;justify-content:space-between;gap:10px;align-items:center;">
        <div>
          <strong style="color:#67e8f9;">🎓 Context Mission</strong>
          <div style="color:#94a3b8;font-size:12px;margin-top:3px;">${stats.runs} runs · ${stats.correct} correct · ${stats.incorrect} to review</div>
        </div>
        <button class="hud-btn" id="start-context-mission-btn">${completed ? '🔁 Practice again' : '▶ Start'}</button>
      </div>
      <div id="context-mission-content" style="margin-top:10px;color:#cbd5e1;">Complete ${chapter.missions.length} situations to finish this chapter.</div>
    </div>
  `;

  detail.querySelectorAll('.learning-audio-btn').forEach(button => {
    button.onclick = () => speakCurriculumText(button.dataset.ko);
  });
  const dialogueAudio = detail.querySelector('.learning-dialogue-audio');
  if (dialogueAudio) dialogueAudio.onclick = () => speakCurriculumDialogue(chapter.id);
  const startButton = document.getElementById('start-context-mission-btn');
  if (startButton) startButton.onclick = () => startContextMission(chapter.id);
  if (learningPathUiState.running && learningPathUiState.chapterId === chapter.id) {
    renderContextMissionQuestion();
  }
}

window.selectLearningChapter = function(chapterId) {
  learningPathUiState = { chapterId, missionIndex:0, missionStartedAt:0, running:false, locked:false };
  curriculumState.activeChapterId = chapterId;
  persistSave();
  renderLearningPath();
};

window.openLearningPath = function(chapterId) {
  playChiptuneSFX('click');
  const desiredId = chapterId || curriculumState.activeChapterId || getRecommendedChapterId();
  learningPathUiState = { chapterId:desiredId, missionIndex:0, missionStartedAt:0, running:false, locked:false };
  setModalState('learning-path-overlay', true);
  renderLearningPath();
};

window.closeLearningPath = function() {
  playChiptuneSFX('click');
  learningPathUiState.running = false;
  setModalState('learning-path-overlay', false);
};

window.speakCurriculumText = function(text) {
  if (text && speakKorean(text)) {
    recordLearningExposure(resolveCurriculumWord(text), 'curriculum_audio');
  }
};

window.speakCurriculumDialogue = function(chapterId) {
  const chapter = window.HVCurriculum?.getChapter(chapterId);
  if (!chapter) return;
  const korean = chapter.dialogue.map(line => line.ko).join(' ');
  if (speakKorean(korean)) {
    chapter.wordRefs.forEach(ko => recordLearningExposure(resolveCurriculumWord(ko), 'curriculum_dialogue_audio'));
  }
};

window.startContextMission = function(chapterId) {
  const chapter = window.HVCurriculum?.getChapter(chapterId);
  if (!chapter?.missions?.length) return;
  learningPathUiState = {
    chapterId,
    missionIndex:0,
    missionStartedAt:Date.now(),
    running:true,
    locked:false
  };
  curriculumState.activeChapterId = chapterId;
  const stats = getChapterAttemptStats(chapterId);
  stats.runs++;
  stats.lastPlayedAt = Date.now();
  persistSave();
  renderLearningPath();
};

function renderContextMissionQuestion() {
  const chapter = window.HVCurriculum?.getChapter(learningPathUiState.chapterId);
  const content = document.getElementById('context-mission-content');
  if (!chapter || !content || !learningPathUiState.running) return;
  if (learningPathUiState.missionIndex >= chapter.missions.length) {
    finishContextMission(chapter);
    return;
  }
  const mission = chapter.missions[learningPathUiState.missionIndex];
  learningPathUiState.missionStartedAt = Date.now();
  learningPathUiState.locked = false;
  const options = [...mission.choicesKo].sort(() => Math.random() - 0.5);
  content.innerHTML = `
    <div style="color:#94a3b8;font-size:12px;">Situation ${learningPathUiState.missionIndex + 1}/${chapter.missions.length}</div>
    <div style="font-weight:800;margin-top:7px;">${escapeLearningHtml(mission.promptVi)}</div>
    <div lang="ko" style="font-family:'Noto Sans KR',sans-serif;font-size:25px;color:#fff;margin-top:9px;">${escapeLearningHtml(mission.contextKo)}
      <button class="hud-btn" id="context-audio-btn" style="padding:3px 7px;">🔊</button>
    </div>
    <div id="context-mission-options">
      ${options.map(option => `<button class="context-choice" data-answer="${escapeLearningHtml(option)}">${escapeLearningHtml(option)}</button>`).join('')}
    </div>
    <div id="context-feedback" style="min-height:24px;margin-top:10px;"></div>
  `;
  const audioButton = document.getElementById('context-audio-btn');
  if (audioButton) audioButton.onclick = () => speakCurriculumText(mission.contextKo.replace('___', mission.correctKo));
  content.querySelectorAll('.context-choice').forEach(button => {
    button.onclick = () => answerContextMission(button.dataset.answer, button);
  });
}

function answerContextMission(answer, button) {
  if (learningPathUiState.locked) return;
  const chapter = window.HVCurriculum?.getChapter(learningPathUiState.chapterId);
  const mission = chapter?.missions?.[learningPathUiState.missionIndex];
  if (!mission) return;
  const isCorrect = answer === mission.correctKo;
  const stats = getChapterAttemptStats(chapter.id);
  recordLearningAttempt(resolveCurriculumWord(mission.correctKo), {
    activity:'npc_ginger_context',
    modality:'context',
    correct:isCorrect,
    responseMs:Date.now() - learningPathUiState.missionStartedAt
  });
  const feedback = document.getElementById('context-feedback');
  if (!isCorrect) {
    stats.incorrect++;
    button.classList.add('wrong');
    playChiptuneSFX('quiz_wrong');
    if (feedback) feedback.innerHTML = `<span style="color:#fca5a5;">❌ Not yet. ${escapeLearningHtml(mission.explanationVi)}</span>`;
    persistSave();
    return;
  }

  learningPathUiState.locked = true;
  stats.correct++;
  button.classList.add('correct');
  document.querySelectorAll('#context-mission-options .context-choice').forEach(choice => { choice.disabled = true; });
  playChiptuneSFX('quiz_correct');
  if (feedback) feedback.innerHTML = `<span style="color:#86efac;">✅ ${escapeLearningHtml(mission.explanationVi)}</span>`;
  persistSave();
  setTimeout(() => {
    learningPathUiState.missionIndex++;
    renderContextMissionQuestion();
  }, 650);
}

function finishContextMission(chapter) {
  const content = document.getElementById('context-mission-content');
  if (!content) return;
  const firstCompletion = !curriculumState.completedChapters.includes(chapter.id);
  if (firstCompletion) {
    curriculumState.completedChapters.push(chapter.id);
    addCoins(30);
  }
  learningPathUiState.running = false;
  persistSave();
  content.innerHTML = `
    <div style="text-align:center;padding:15px;">
      <div style="font-size:38px;">${firstCompletion ? '🌟' : '✅'}</div>
      <div style="color:#86efac;font-weight:900;margin-top:6px;">Completed ${escapeLearningHtml(chapter.titleVi)}!</div>
      <div style="color:#94a3b8;margin-top:5px;">${firstCompletion ? 'First-time reward: 30 🪙' : 'Review progress recorded.'}</div>
      <button class="hud-btn" style="margin-top:12px;" onclick="renderLearningPath()">Continue learning path</button>
    </div>
  `;
  const summary = document.getElementById('learning-path-summary');
  if (summary) {
    summary.textContent = `${curriculumState.completedChapters.length}/${getCurriculumChapters().length} chapters complete · learn words in sentences · practice in context`;
  }
  showToast(`🎓 Ginger Mission complete${firstCompletion ? ' · +30 🪙' : ''}!`, 2400);
}

// ═══════════════ SHOP ════════════════════════════════════════════════════════
function openShop(options = {}) {
  if (!options.skipWorldMission && typeof window.launchZoneLearning === 'function') {
    const launched = window.launchZoneLearning('shop', () => openShop({ skipWorldMission:true }));
    if (launched) return;
  }
  playChiptuneSFX('click');
  shopOpen = true;
  updateGoldHUD();
  buildShopGrid();
  setModalState('shop-overlay', true);
}
function closeShop() {
  playChiptuneSFX('click');
  shopOpen = false;
  setModalState('shop-overlay', false);
}

function _doLevelPurchase(idx) {
  const cost = LEVEL_COST(idx);
  if(unlockedLevels.includes(idx)) { showToast('You already own this pack!'); return false; }
  const gate = getPackLearningGate(idx);
  if (!gate.allowed) { showToast(gate.message, 4000); return false; }
  if(!spendCoins(cost)) { showToast(`Need ${cost} Coins! You have ${playerCurrencies.coins} 🪙`); return false; }
  unlockedLevels.push(idx);
  if(sceneRef) sceneRef.refreshPlotAccess();
  showToast(`🎉 Unlocked "${levelsData[idx].name}"! Welcome to Level ${levelsData[idx].level}!`, 4500);
  return true;
}
function buyLevel(idx) {
  playChiptuneSFX('click');
  const cost = LEVEL_COST(idx);
  if (unlockedLevels.includes(idx)) { showToast('You already own this pack!'); return; }
  const gate = getPackLearningGate(idx);
  if (!gate.allowed) { showToast(gate.message, 4000); return; }
  if (playerCurrencies.coins < cost) { showToast(`Need ${cost} Coins! You have ${playerCurrencies.coins} 🪙`); return; }
  startShopQuizGate(idx);
}
function buyPlotExpansion(idx) {
  if (typeof playChiptuneSFX === 'function') playChiptuneSFX('click');
  const plotIndex = 9 + idx;
  const cost = PLOT_UNLOCK_COSTS[idx] || 1000;

  if (isPlotUnlocked(plotIndex)) {
    showToast('You already unlocked this farm plot!');
    return;
  }

  if (playerCurrencies.coins < cost) {
    if (typeof playChiptuneSFX === 'function') playChiptuneSFX('quiz_wrong');
    showToast(`Need ${cost} Gold 🪙 to unlock Farm Plot #${plotIndex + 1}!`);
    return;
  }

  spendCoins(cost);
  if (!unlockedPlots.includes(plotIndex)) unlockedPlots.push(plotIndex);
  unlockedPlotCount = Math.max(unlockedPlotCount, unlockedPlots.length);

  if (sceneRef) {
    const p = sceneRef.plots ? sceneRef.plots[plotIndex] : null;
    if (p && typeof sceneRef.unlockPlot === 'function') {
      sceneRef.unlockPlot(p);
    } else if (typeof sceneRef.refreshPlotAccess === 'function') {
      sceneRef.refreshPlotAccess();
    }
  }

  persistSave();
  showToast(`🎉 Unlocked Farm Plot #${plotIndex + 1}!`);
  buildShopGrid();
  updateGoldHUD();
}

function buildShopGrid() {
  const grid = $('shop-level-grid'); if(!grid) return; grid.innerHTML = '';

  // Section 1: Farm Plot Expansions
  const plotHeader = document.createElement('div');
  plotHeader.className = 'shop-section-header';
  plotHeader.style.cssText = 'grid-column: 1 / -1; font-family: "Press Start 2P", monospace; font-size: 13px; color: var(--neon-gold, #FBBF24); margin: 10px 0 6px 0; padding-bottom: 6px; border-bottom: 1px solid rgba(251, 191, 36, 0.3); display: flex; align-items: center; gap: 8px;';
  plotHeader.innerHTML = `🌾 Farm Plot Expansions (${unlockedPlots.length}/15 Unlocked)`;
  grid.appendChild(plotHeader);

  PLOT_UNLOCK_COSTS.forEach((cost, idx) => {
    const plotIndex = 9 + idx;
    const isOwned = isPlotUnlocked(plotIndex);
    const canAfford = playerCurrencies.coins >= cost;

    const card = document.createElement('div');
    card.className = 'shop-card' + (isOwned ? ' owned' : (!canAfford ? ' too-expensive' : ''));
    card.innerHTML = `
      <div class="shop-card-icon">🌾</div>
      <div class="shop-card-name">Plot #${idx + 1} Expansion</div>
      <div class="shop-card-desc">Unlock Farm Plot #${plotIndex + 1} for ${cost} Gold</div>
      <div class="shop-card-price">
        ${isOwned
          ? `<span class="shop-owned-badge">✅ Owned</span>
             <button class="shop-buy-btn" disabled>Unlocked</button>`
          : `<span class="shop-card-cost">💰 ${cost} gold</span>
             <button class="shop-buy-btn" ${canAfford ? '' : 'disabled'} onclick="buyPlotExpansion(${idx})">
               ${canAfford ? '🛒 Buy Now' : `Need ${cost - playerCurrencies.coins} gold`}
             </button>`}
      </div>`;
    grid.appendChild(card);
  });

  // Section 2: Vocabulary Level Packs
  const lvlHeader = document.createElement('div');
  lvlHeader.className = 'shop-section-header';
  lvlHeader.style.cssText = 'grid-column: 1 / -1; font-family: "Press Start 2P", monospace; font-size: 13px; color: var(--neon-cyan, #38BDF8); margin: 20px 0 6px 0; padding-bottom: 6px; border-bottom: 1px solid rgba(56, 189, 248, 0.3); display: flex; align-items: center; gap: 8px;';
  lvlHeader.innerHTML = `📚 Vocabulary Level Packs`;
  grid.appendChild(lvlHeader);

  levelsData.forEach((lvl, idx) => {
    const owned     = unlockedLevels.includes(idx);
    const cost      = LEVEL_COST(idx);
    const canAfford = gold >= cost;

    const card = document.createElement('div');
    card.className = 'shop-card' + (owned ? ' owned' : (!canAfford ? ' too-expensive' : ''));
    card.innerHTML = `
      <div class="shop-card-icon">${lvl.icon||'📚'}</div>
      <div class="shop-card-name">Level ${lvl.level}: ${lvl.name}</div>
      <div class="shop-card-desc">${lvl.description||''} — ${lvl.words.length} words</div>
      <div class="shop-card-price">
        ${owned
          ? `<span class="shop-owned-badge">✅ Owned</span>
             <button class="shop-buy-btn" onclick="closeShop();startLevel(${idx})">🌾 Play</button>`
          : `<span class="shop-card-cost">💰 ${cost} gold</span>
             <button class="shop-buy-btn" ${canAfford?'':'disabled'} onclick="buyLevel(${idx})">
               ${canAfford ? '🛒 Buy Now' : `Need ${cost-gold} more gold`}
             </button>`}
      </div>`;
    grid.appendChild(card);
  });
}
$('shop-close-btn').addEventListener('click', closeShop);
$('shop-btn').addEventListener('click', openShop);
$('shop-overlay').addEventListener('keydown', e => e.stopPropagation());

// ═══════════════ VOCAB BOOK ══════════════════════════════════════════════════
let activeCat = 'all';
let activeMasteryFilter = 'all';

function buildVocabBook() {
  if(!levelsData.length) return;
  const lvl = levelsData[currentLevelIndex];
  vocabSubtitle.textContent = `Level ${lvl.level} – ${lvl.name}`;
  const cats = ['all', '⚪ Novice', '🔵 Practicing', '🟣 Mastered', '🟡 Legendary', ...new Set(lvl.words.map(w => w.category).filter(Boolean))];
  catFiltersEl.innerHTML = '';
  cats.forEach(cc => {
    const b = document.createElement('button');
    b.className = 'cat-filter-btn' + (cc === activeCat ? ' active' : '');
    b.textContent = cc === 'all' ? '🌐 All' : cc;
    b.onclick = () => { activeCat = cc; buildVocabBook(); };
    catFiltersEl.appendChild(b);
  });
  renderVocabCards();
}
